    "questionAr": "عينة حجمها $10\\text{ mL}$ من خل تجاري (يحتوي على حمض الأسيتيك $\\text{CH}_3\\text{COOH}$، كتلته المولية $60\\text{ g/mol}$) عويرت بمحلول $\\text{NaOH}$ تركيزه $0.5\\text{ M}$. فإذا لزم $16\\text{ mL}$ من القاعدة للوصول لنقطة النهاية، فإن تركيز حمض الأسيتيك في الخل يساوي:",
    "optionsEn": [
      "$0.4\\text{ M}$",
      "$0.8\\text{ M}$",
      "$1.6\\text{ M}$",
      "$0.5\\text{ M}$"
    ],
    "optionsAr": [
      "$0.4\\text{ M}$",
      "$0.8\\text{ M}$",
      "$1.6\\text{ M}$",
      "$0.5\\text{ M}$"
    ],
    "correctAnswer": "$0.8\\text{ M}$",
    "correctIndex": 1,
    "hintEn": "$M_a \\times 10 = 0.5 \\times 16 \\implies M_a = 8 / 10 = 0.8\\text{ M}$.",
    "hintAr": "$M_a \\times 10 = 0.5 \\times 16 \\implies M_a = 8 / 10 = 0.8\\text{ M}$.",
    "stepByStepSolutionEn": [
      "Reaction: $\\text{CH}_3\\text{COOH} + \\text{NaOH} \\to \\text{CH}_3\\text{COONa} + \\text{H}_2\\text{O}$ ($n_a = 1, n_b = 1$). $M_a V_a = M_b V_b \\implies M_a \\times 10 = 0.5 \\times 16 = 8 \\implies M_a = \\frac{8}{10} = 0.8\\text{ M}$."
    ],
    "stepByStepSolutionAr": [
      "تفاعل أحادي البروتون: $\\text{CH}_3\\text{COOH} + \\text{NaOH} \\to \\text{CH}_3\\text{COONa} + \\text{H}_2\\text{O}$ ($n_a = 1, n_b = 1$). $M_a \\times 10 = 0.5 \\times 16 = 8 \\implies M_a = 0.8\\text{ M}$."
    ],
    "teacherTipEn": "Acetic acid is monobasic: $M_a V_a = M_b V_b$.",
    "teacherTipAr": "حمض الأسيتيك أحادي القاعدية ويتعادل بنسبة 1:1 مع الصودا الكاوية."
