    "questionEn": "A sample of hydrated washing soda ($\\text{Na}_2\\text{CO}_3 \\cdot 10\\text{H}_2\\text{O}$, $M_m = 286\\text{ g/mol}$) weighing $14.3\\text{ g}$ is heated until all water of crystallization evaporates. The mass of the remaining anhydrous sodium carbonate ($\\text{Na}_2\\text{CO}_3$, $M_m = 106\\text{ g/mol}$) is:",
