    "hintAr": "المولات المتبقية من الحمض = $0.005\\text{ mol}$. الحجم الكلي = $0.2\\text{ L}$. $[\\text{H}^+] = 0.025\\text{ M}$. $\\text{pH} = -\\log(0.025) = 1.60$.",
