    "hintAr": "مولات الحمض = $0.02\\text{ mol}$. مولات الملح النقي = $0.01\\text{ mol}$. كتلته = $1.06\\text{ g}$. نسبة النقاء = $(1.06 / 1.5) \\times 100 = 70.67\\%$.",
