    "difficulty": "hots",
    "questionEn": "When $10.0\\text{ g}$ of hydrated sodium carbonate crystals ($\\text{Na}_2\\text{CO}_3 \\cdot 10\\text{H}_2\\text{O}$, $M_m = 286\\text{ g/mol}$) is exposed to dry air for several days (efflorescence), its mass drops to $4.34\\text{ g}$. If anhydrous $\\text{Na}_2\\text{CO}_3$ has $M_m = 106\\text{ g/mol}$, the formula of the resulting effloresced hydrate ($\\text{Na}_2\\text{CO}_3 \\cdot y\\text{H}_2\\text{O}$) is:",
    "questionAr": "عند تعريض $10.0\\text{ g}$ من بلورات كربونات الصوديوم المتهدرتة ($\\text{Na}_2\\text{CO}_3 \\cdot 10\\text{H}_2\\text{O}$، كتلته المولية $286\\text{ g/mol}$) للهواء الجاف لعدة أيام (ظاهرة التزهر)، انخفضت كتلتها إلى $4.34\\text{ g}$. فإذا كانت الكتلة المولية للملح اللامائي $106\\text{ g/mol}$، فإن صيغة الملح المتزهر الناتج ($\\text{Na}_2\\text{CO}_3 \\cdot y\\text{H}_2\\text{O}$) هي:",
